Variables quantitatives

Test t de Student pour échantillons indépendants
\[\begin{cases} H_0: \mu_e = \mu_p \\H_1:\mu_e \ne \mu_p \end{cases} | \ \text{Au risque} \ \alpha = 5 \% \ \text{, on a une} \ p_{value}&lt;0.05\]

quant &lt;- which(sapply(df, is.numeric))

ttest_val &lt;- map_dfr(quant, ~ t.test(df[[.x]] ~ df$churn, var.equal = FALSE) |&gt;
  tidy() |&gt;
  mutate(Variable = names(df)[.x]))


ttest &lt;- data.frame(ttest_val) |&gt;
  mutate(
    Variable = factor(Variable, levels = names(df)),
    estimate = round(estimate, 2),
    estimate1 = round(estimate1, 2),
    estimate2 = round(estimate2, 2),
    p.value = formatC(p.value, format = "e", digits = 2),
    conf.low = round(conf.low, 2),
    conf.high = round(conf.high, 2)
  )

ttest |&gt;
  dplyr::select(Variable, estimate, estimate1, estimate2, p.value, conf.low, conf.high) |&gt;
  rename(
    `Variable` = Variable,
    `Estimate` = estimate,
    `µ1` = estimate1,
    `µ2` = estimate2,
    `IC inf` = conf.low,
    `IC sup` = conf.high,
    `p-value` = p.value
  ) |&gt;
  tableau_html(titre = "Résultats des tests de student", format = "markdown", small = TRUE) |&gt; 
  column_spec(1, bold = TRUE) |&gt; 
  row_spec(0, bold = TRUE) |&gt; 
  column_spec(6, color = ifelse(ttest_val[,5] &gt; 0.05, "red", "black"))

